def merge_intervals(intervals):
    """Return the union of [start, end] intervals.

    Overlapping intervals and intervals that merely touch at an endpoint are
    merged.  Isolated zero-width intervals are preserved, and duplicates are
    removed.  The result is sorted by start, then end.
    """
    if not intervals:
        return []

    ordered = sorted((list(interval) for interval in intervals),
                     key=lambda pair: (pair[0], pair[1]))

    merged = [ordered[0]]
    for start, end in ordered[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            # Overlap or touch: extend the current interval when needed.
            if end > last_end:
                merged[-1] = [last_start, end]
        else:
            merged.append([start, end])

    return merged

