"""Parse compact duration strings such as ``"1h2m3s"`` into seconds."""

import re

# ASCII digits only: \d would also match non-ASCII decimal digits.
_DURATION_PATTERN = re.compile(
    r"(?:(?P<hours>[0-9]+)h)?"
    r"(?:(?P<minutes>[0-9]+)m)?"
    r"(?:(?P<seconds>[0-9]+)s)?"
)


def _parse_count(digits):
    """Return the integer value of an ASCII digit run, or None if malformed."""
    if len(digits) > 1 and digits[0] == "0":
        return None
    return int(digits)


def parse_duration(text):
    """Return the number of seconds described by ``text``, or None if invalid."""
    if not isinstance(text, str):
        return None

    match = _DURATION_PATTERN.fullmatch(text)
    if match is None:
        return None

    hours_text, minutes_text, seconds_text = match.group("hours", "minutes", "seconds")
    if hours_text is None and minutes_text is None and seconds_text is None:
        return None

    total = 0

    if hours_text is not None:
        hours = _parse_count(hours_text)
        if hours is None:
            return None
        total += hours * 3600

    for value_text, limit, factor in (
        (minutes_text, 59, 60),
        (seconds_text, 59, 1),
    ):
        if value_text is None:
            continue
        value = _parse_count(value_text)
        if value is None or value > limit:
            return None
        total += value * factor

    return total

