"""Parse compact duration strings such as ``1h2m3s`` into seconds."""

import re

# h, then m, then s: each optional, each at most once, in that order.
_PATTERN = re.compile(r"(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?")

_LIMITS = ((None, 3600), (59, 60), (59, 1))


def _to_int(digits):
    """Convert an ASCII digit string to int without int()'s digit limit."""
    value = 0
    for char in digits:
        value = value * 10 + (ord(char) - 48)
    return value


def _parse_count(digits, maximum):
    """Return the integer value of ``digits`` or None if it is out of range."""
    if digits is None:
        return 0
    if len(digits) > 1 and digits[0] == "0":
        return None
    value = _to_int(digits)
    if maximum is not None and value > maximum:
        return None
    return value


def parse_duration(text):
    """Return the number of seconds encoded in ``text``, or None if invalid."""
    if not isinstance(text, str):
        return None

    match = _PATTERN.fullmatch(text)
    if match is None:
        return None

    hours, minutes, seconds = match.groups()
    if hours is None and minutes is None and seconds is None:
        return None

    total = 0
    for digits, (maximum, multiplier) in zip(match.groups(), _LIMITS):
        count = _parse_count(digits, maximum)
        if count is None:
            return None
        total += count * multiplier
    return total
